hl.device({
    name = "epic-mouse-v1",
    sensitivity = -0.5,
})

local mainMod = "CTRL" -- Sets Control key as main modifier

hl.bind(mainMod .. " + return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + Q", hl.dsp.window.close())
hl.bind(mainMod .. " + M", hl.dsp.exit())
hl.bind("ALT_L + E", hl.dsp.exec_cmd(fileManager))
hl.bind("ALT_L + F", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + space", hl.dsp.exec_cmd(menu))
hl.bind("ALT_L + P", hl.dsp.window.pseudo())

hl.bind(mainMod .. " + SHIFT + F10", hl.dsp.exec_cmd("grimshot --cursor copy area"))

hl.bind("ALT + H", hl.dsp.focus({ direction = "left" }))
hl.bind("ALT + L", hl.dsp.focus({ direction = "right" }))
hl.bind("ALT + K", hl.dsp.focus({ direction = "up" }))
hl.bind("ALT + J", hl.dsp.focus({ direction = "down" }))

hl.bind("ALT + SHIFT + H", hl.dsp.window.move({ direction = "left" }))
hl.bind("ALT + SHIFT + L", hl.dsp.window.move({ direction = "right" }))
hl.bind("ALT + SHIFT + K", hl.dsp.window.move({ direction = "up" }))
hl.bind("ALT + SHIFT + J", hl.dsp.window.move({ direction = "down" }))

hl.bind(mainMod .. " + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + 5", hl.dsp.focus({ workspace = 5 }))
